pub fn vm_uid_drop_active() -> bool {
    let is_root = unsafe { libc::geteuid() } == 0;
    let opted_out =
        std::env::var_os("SMOLVM_VM_UID_DROP").as_deref() == Some(std::ffi::OsStr::new("off"));
    is_root && !opted_out
}

